INSERT INTO `agents` (`id`, `workspace_id`, `agent_key`, `name`, `instructions`, `model_id`, `reasoning`, `approval_ttl_seconds`, `status`, `created_at`, `updated_at`) VALUES (1,1,'default','Assistant','You are the Acme assistant. Answer from the knowledge you are given before you answer from memory, and say plainly when you do not know. Be brief: a person reading you is usually in the middle of something else.',2,0,NULL,'active','2026-07-14 21:30:08.563','2026-07-14 21:30:08.563');
INSERT INTO `agents` (`id`, `workspace_id`, `agent_key`, `name`, `instructions`, `model_id`, `reasoning`, `approval_ttl_seconds`, `status`, `created_at`, `updated_at`) VALUES (2,1,'support','Support Assistant','You help the support team answer customer questions. Ground every answer in the support playbook and quote the policy you are relying on. If a question needs a refund, a credit, or anything that touches a customer\'s money, say what you would do and hand it to a person: you propose, they decide.',2,0,3600,'active','2026-07-14 21:30:08.569','2026-07-14 21:30:08.569');
INSERT INTO `agents` (`id`, `workspace_id`, `agent_key`, `name`, `instructions`, `model_id`, `reasoning`, `approval_ttl_seconds`, `status`, `created_at`, `updated_at`) VALUES (3,1,'sales','Sales Assistant','You help the sales team prepare for calls. Use the sales playbook for pricing, positioning and objection handling. Never invent a discount or a commitment we have not made, and never quote a price that is not in the playbook.',4,0,NULL,'active','2026-07-14 21:30:08.572','2026-07-14 21:30:08.572');
INSERT INTO `agents` (`id`, `workspace_id`, `agent_key`, `name`, `instructions`, `model_id`, `reasoning`, `approval_ttl_seconds`, `status`, `created_at`, `updated_at`) VALUES (4,1,'engineering','Engineering Copilot','You help engineers operate the platform. Prefer the runbook over your own recollection. When an action would change a running system, describe the change and its blast radius before you propose it.',1,1,900,'active','2026-07-14 21:30:08.580','2026-07-14 21:30:08.580');
INSERT INTO `agents` (`id`, `workspace_id`, `agent_key`, `name`, `instructions`, `model_id`, `reasoning`, `approval_ttl_seconds`, `status`, `created_at`, `updated_at`) VALUES (5,1,'curator','Knowledge Curator','You keep the knowledge base honest. When you find an answer that the knowledge base contradicts, say so and quote both. When you find a gap, say what is missing rather than filling it with a guess.',9,1,NULL,'active','2026-07-14 21:30:08.589','2026-07-14 21:30:08.589');
